## Turn package://, file:// or a bare path into an absolute filesystem path.
static func resolve_uri(uri: String) -> String:
	uri = uri.strip_edges()
	if uri.is_empty():
		return ""
	if uri.begins_with("package://"):
		var rest := uri.substr("package://".length())
		var slash := rest.find("/")
		if slash < 0:
			return ""
		var pkg := rest.substr(0, slash)
		var relative := rest.substr(slash + 1)
		var share := package_share_dir(pkg)
		if share.is_empty():
			return ""
		return share.path_join(relative)
	if uri.begins_with("file://"):
		return uri.substr("file://".length())
	if uri.begins_with("res://") or uri.begins_with("user://"):
		return ProjectSettings.globalize_path(uri)
	return uri


## The share directory of an installed ROS package, cached.
static func package_share_dir(pkg: String) -> String:
	if _package_paths.has(pkg):
		return _package_paths[pkg]
	for prefix in OS.get_environment("AMENT_PREFIX_PATH").split(":", false):
		var candidate := prefix.path_join("share").path_join(pkg)
		if DirAccess.dir_exists_absolute(candidate):
			_package_paths[pkg] = candidate
			return candidate
	_package_paths[pkg] = ""
	return ""


static func _load_gltf(path: String) -> Dictionary:
	var doc := GLTFDocument.new()
	var state := GLTFState.new()
	var err := doc.append_from_file(path, state)
	if err != OK:
		return {"ok": false, "error": "glTF load failed (error %d)" % err}
	var scene := doc.generate_scene(state)
	if scene == null:
		return {"ok": false, "error": "glTF produced no scene"}

	var verts := PackedVector3Array()
	var normals := PackedVector3Array()
	var colors := PackedColorArray()
	_collect_meshes(scene, Transform3D.IDENTITY, verts, normals, colors)
	scene.queue_free()

	# glTF is Y-up and metres, the same as Godot, so no axis mapping applies
	# here — unlike the ROS-authored formats above.
	var mesh := VizShapes.triangles(verts, colors, normals)
	if mesh == null:
		return {"ok": false, "error": "glTF contained no triangles"}
	return {"ok": true, "mesh": mesh}


static func _collect_meshes(node: Node, parent: Transform3D, verts: PackedVector3Array,
		normals: PackedVector3Array, colors: PackedColorArray) -> void:
